'use strict';
const $=id=>document.getElementById(id),t=OrionI18n.t;
const arrows=['↑','→','↓','←'],names=[['Up','上'],['Right','右'],['Down','下'],['Left','左']],vectors=[[0,-1],[1,0],[0,1],[-1,0]];
// Each route is a connected path; rotations/reflections create eight persistent sets.
const paths=[[[0,4],[1,4],[2,4],[2,3],[2,2],[3,2],[4,2]],[[0,4],[0,3],[0,2],[1,2],[2,2],[2,1],[2,0],[3,0],[4,0]],[[0,4],[1,4],[2,4],[2,3],[2,2],[1,2],[0,2],[0,1],[0,0],[1,0],[2,0],[3,0],[4,0]]];
let variant=OrionProgress.variant('fox'),observedVariant=variant,observedTarget=OrionProgress.read().hashTarget;
let stage=0,program=[],position=[0,4],trail=[],solved=false,running=false,timer=null,token=0,hintDepth=0,state='ready',active=-1,steps=0,saveFailed=false;
function route(v=variant,s=stage){return paths[s].map(([x,y])=>{if(v>=4)x=4-x;for(let i=0;i<v%4;i++)[x,y]=[4-y,x];return[x,y];});}
const same=(a,b)=>a[0]===b[0]&&a[1]===b[1];
function advance(pos,d,map){const delta=vectors[d];if(!delta)return null;const next=[pos[0]+delta[0],pos[1]+delta[1]];return map.some(p=>same(p,next))?next:null;}
function expand(commands){if(!Array.isArray(commands)||commands.length>12)return null;const out=[];for(let i=0;i<commands.length;i++){const c=commands[i];if(!c||!Number.isInteger(c.d)||c.d<0||c.d>3||!Number.isInteger(c.n)||c.n<1||c.n>3)return null;for(let n=0;n<c.n;n++)out.push({d:c.d,card:i});}return out;}
function simulate(commands,map=route()){const list=expand(commands);let pos=map[0];if(!list||!list.length)return{success:false,reason:'empty',position:pos};for(const c of list){const next=advance(pos,c.d,map);if(!next)return{success:false,reason:'bump',position:pos};pos=next;}return{success:same(pos,map.at(-1)),reason:same(pos,map.at(-1))?'success':'short',position:pos};}
function solution(){const p=route(),out=[];for(let i=1;i<p.length;i++){const d=vectors.findIndex(v=>v[0]===p[i][0]-p[i-1][0]&&v[1]===p[i][1]-p[i-1][1]);const last=out.at(-1);if(last&&last.d===d&&last.n<3)last.n++;else out.push({d,n:1});}return out;}
function cancelRun(){token++;if(timer!==null)clearTimeout(timer);timer=null;running=false;active=-1;}
function resetTrial(){cancelRun();program=[];position=route()[0];trail=[position];steps=0;solved=false;hintDepth=0;state='ready';saveFailed=false;$('repeat').value='1';$('notes').open=false;render();}
function resetMission(v=OrionProgress.variant('fox')){variant=v;stage=0;resetTrial();}
function addCommand(d,n=Number($('repeat').value)){if(running||solved||!Number.isInteger(d)||d<0||d>3||!Number.isInteger(n)||n<1||n>3)return;if(program.length===12){state='full';render();return;}program.push({d,n});state='edited';render();}
function removeCommand(i){if(running||solved||!Number.isInteger(i)||i<0||i>=program.length)return;program.splice(i,1);state='edited';render();}
function run(){if(running||solved)return;const list=expand(program);if(!list||!list.length){state='empty';render();return;}cancelRun();running=true;position=route()[0];trail=[position];steps=0;state='running';const current=token;let index=0;render();
 function tick(){if(current!==token)return;if(index===list.length){running=false;timer=null;active=-1;solved=same(position,route().at(-1));state=solved?'success':'short';if(solved&&stage===2)saveFailed=!OrionProgress.earn('footprint');render();if(solved&&stage<2)$('next').focus();return;}const cmd=list[index++];active=cmd.card;const next=advance(position,cmd.d,route());if(!next){running=false;timer=null;state='bump';render();return;}position=next;trail.push(position);steps++;render();timer=setTimeout(tick,420);}timer=setTimeout(tick,420);
}
function hints(){return[t('Start at the fox. Trace the pale stone path to the treasure, one square at a time. Arrows always mean screen directions.','從狐狸開始，沿淺色石路逐格走到寶藏。箭頭一直代表畫面的方向。'),t('Commands run in order. Repeat ×2 means take the same step twice. If the fox meets a hedge, remove the wrong command and try again.','指令會依次執行。重複 ×2 就是同一步做兩次。狐狸碰到樹籬時，刪掉錯誤指令，再試一次。'),t('One working program: ','其中一個可行程式：')+solution().map(c=>`${arrows[c.d]} ×${c.n}`).join(' · ')];}
function render(){const map=route(),goal=map.at(-1),complete=solved&&stage===2,count=stage+Number(solved);window.OrionDiscovery?.update(complete);document.title=t('The Clockwork Fox · Orion','迷路的機械狐狸 · Orion');$('stageTitle').textContent=t(`Garden ${stage+1} · Set ${variant+1}`,`第 ${stage+1} 座花園 · 第 ${variant+1} 組`);$('sceneStatus').textContent=t(`Treasure paths found · ${count} / 3`,`已找到 ${count} / 3 條寶藏路線`);$('seals').textContent=Array.from({length:3},(_,i)=>i<count?'◆':'◇').join(' ');$('scene').classList.toggle('complete',complete);
$('board').innerHTML=Array.from({length:25},(_,i)=>{const p=[i%5,Math.floor(i/5)],fox=same(p,position),end=same(p,goal),start=same(p,map[0]),path=map.some(q=>same(p,q)),visited=trail.some(q=>same(p,q));const label=t(`Row ${p[1]+1}, column ${p[0]+1}: `,`第 ${p[1]+1} 行，第 ${p[0]+1} 列：`)+(fox?t('fox','狐狸'):end?t('treasure','寶藏'):start?t('start','起點'):path?t('path','石路'):t('hedge','樹籬'));return `<div role="img" aria-label="${label}" class="tile ${path?'path':'hedge'} ${visited?'visited':''} ${fox?'fox':''} ${end?'treasure':''}"><span aria-hidden="true">${fox?'🦊':end?'◆':start?'⚑':path?'·':'♣'}</span></div>`;}).join('');
$('queue').innerHTML=program.map((c,i)=>`<button type="button" data-remove="${i}" ${running||solved?'disabled':''} class="command ${i===active?'active':''}" aria-label="${t(`Remove command ${i+1}: ${names[c.d][0]} repeated ${c.n} times`,`刪除指令 ${i+1}：向${names[c.d][1]}重複 ${c.n} 次`)}"><small>${i+1}</small> ${arrows[c.d]} ×${c.n} <span aria-hidden="true">×</span></button>`).join('')||`<p class="empty">${t('Your commands appear here. Tap an arrow to add one.','指令會排在這裡。點箭頭加入指令。')}</p>`;
$('queueCount').textContent=t(`${program.length} / 12 commands · ${expand(program)?.length??0} steps`,`${program.length} / 12 個指令 · ${expand(program)?.length??0} 步`);$('reading').textContent=t(`Fox: row ${position[1]+1}, column ${position[0]+1} · ${steps} steps walked`,`狐狸：第 ${position[1]+1} 行，第 ${position[0]+1} 列 · 已走 ${steps} 步`);
const messages={ready:t('Choose a repeat count, then tap arrows. Press Run to watch your plan.','選擇重複次數，再點箭頭。按「執行」看看你的計劃。'),edited:t('Read your commands from left to right. Tap a command to remove it.','由左至右讀指令。點一下指令就能刪除。'),empty:t('Add at least one arrow first.','先加入至少一個箭頭。'),full:t('The tray holds 12 commands. Remove one, or use Repeat for matching steps.','最多可放 12 個指令。刪掉一個，或用「重複」合併相同步驟。'),running:t('Watch the glowing command. The fox follows it one step at a time.','看看發光的指令。狐狸正在逐步執行。'),bump:t('A hedge blocks that step. Nothing is lost! Edit your plan; Run starts from the flag again.','這一步被樹籬擋住了。沒關係！修改計劃；再次執行會從旗子出發。'),short:t('The program ended away from the treasure. Add or change commands, then run again.','程式結束時還未到寶藏。加入或修改指令，再執行一次。'),stopped:t('Paused here for a look. Run starts your whole plan again from the flag.','停在這裡觀察。再次執行會從旗子重新開始整個計劃。'),success:t('Your program brought the fox to the treasure!','你的程式成功帶狐狸走到寶藏！')};$('feedback').textContent=messages[state];
for(const id of ['up','right','down','left','repeat','clear'])$(id).disabled=running||solved;$('run').hidden=solved;$('run').disabled=running;$('stop').hidden=!running;$('next').hidden=!solved||stage===2;$('reward').hidden=!complete;$('notes').hidden=!complete;$('hint').disabled=running||solved||hintDepth===3;$('hint').setAttribute('aria-label',t('Reveal the next clue','顯示下一個提示'));$('hint').setAttribute('aria-expanded',String(hintDepth>0));$('hints').hidden=!hintDepth;$('hints').innerHTML=hints().slice(0,hintDepth).map(h=>`<li>${h}</li>`).join('');$('retrySave').hidden=!saveFailed;$('saveStatus').textContent=saveFailed?t('Sigil earned, but saving failed. Try saving again.','已獲得符印，但儲存失敗。請再次儲存。'):OrionProgress.has('footprint')?t('Footprint Sigil saved in your collection.','足跡符印已存入收藏。'):'';}
['up','right','down','left'].forEach((id,d)=>$(id).onclick=()=>addCommand(d));$('queue').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b)removeCommand(Number(b.dataset.remove));});$('run').onclick=run;$('stop').onclick=()=>{if(!running)return;cancelRun();state='stopped';render();};$('clear').onclick=()=>{if(!running&&!solved)resetTrial();};$('next').onclick=()=>{if(!solved||stage===2)return;stage++;resetTrial();$('up').focus();};$('hint').onclick=()=>{if(running||solved)return;hintDepth=Math.min(3,hintDepth+1);render();};$('replay').onclick=()=>{const v=OrionProgress.nextVariant('fox',variant);observedVariant=OrionProgress.variant('fox');resetMission(v);};$('retrySave').onclick=()=>{if(!solved||stage!==2)return;saveFailed=!OrionProgress.earn('footprint');render();};
function syncProgress(){const v=OrionProgress.variant('fox'),h=OrionProgress.read().hashTarget,changed=v!==observedVariant||h!==observedTarget;observedVariant=v;observedTarget=h;if(changed||solved&&stage===2&&!OrionProgress.has('footprint')&&!saveFailed)resetMission();else render();}
window.addEventListener('orion-language',render);window.addEventListener('storage',e=>{if(e.key==='orion-expedition-progress-v1'||e.key===null)syncProgress();});window.addEventListener('pageshow',syncProgress);window.addEventListener('pagehide',()=>{if(running){cancelRun();state='stopped';}});resetMission();OrionI18n.apply();
